package com.nexamart.backend.repository;import com.nexamart.backend.domain.Notification;import com.nexamart.backend.domain.Role;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;public interface NotificationRepository extends JpaRepository<Notification,Long>{Page<Notification> findByUserId(Long userId,Pageable p);java.util.List<Notification> findTop20ByUserRoleOrderByCreatedAtDesc(Role role);long countByUserRoleAndReadFlagFalse(Role role);long countByUserIdAndReadFlagFalse(Long userId);java.util.List<Notification> findByUserIdAndReadFlagFalse(Long userId);@Query("select n from Notification n where n.user.id=:userId and (:unreadOnly=false or n.readFlag=false) order by n.createdAt desc")Page<Notification> search(@Param("userId")Long userId,@Param("unreadOnly")boolean unreadOnly,Pageable p);}
